 $components=$db->query("SELECT payment_id FROM {$p}company_bank_receipt_components WHERE invoice_id IN (?,?)",[$pair['apiInvoice'],$pair['cnabInvoice']])->result_array();$componentWinner=!$none&&$winners[0]===1&&$pair['cnabRequest']['source']==='components';essentialCheck(count($components)===($componentWinner?1:0),'only winning component source can create its immutable decomposition');$journal=$db->query("SELECT kind,source_id FROM {$p}company_financial_events WHERE source_type='payment' AND source_id IN(SELECT CAST(id AS CHAR) FROM {$p}invoicepaymentrecords WHERE invoiceid IN (?,?))",[$pair['apiInvoice'],$pair['cnabInvoice']])->result_array();essentialCheck(count($journal)===($none?0:($componentWinner?2:1)),'one cash journal and optional winning decomposition, no duplicate financial event');
